let now = global.get("now");

if (!now || !now.startTime || !now.startTimestamp) {
    // เริ่มต้นจาก nowString เดิม (ควรตั้งไว้ก่อน)
    now = global.get("now") || {};
    const nowString = now.nowString;

    const match = nowString && nowString.match(/(\d{4})-(\d{2})-(\d{2}) เวลา (\d{2}):(\d{2}):(\d{2})/);
    if (!match) {
        node.error("รูปแบบ nowString ไม่ถูกต้อง", msg);
        return null;
    }

    const [_, y, m, d, hh, mm, ss] = match;
    const baseDate = new Date(`${y}-${m}-${d}T${hh}:${mm}:${ss}`);

    now.startTime = baseDate.getTime();     // เวลาเริ่มต้นใน ms
    now.startTimestamp = Date.now();        // เวลาที่ inject เริ่มต้น
    global.set("now", now);
    node.status({ fill: "blue", shape: "dot", text: now.nowString });
    msg.payload = now.nowString;
    return msg;
}

// เวลาที่ผ่านไปจริง
const nowTimestamp = Date.now();
const elapsed = nowTimestamp - now.startTimestamp;  // ms ที่ผ่านไป
