const y = newTime.getFullYear();
const m = String(newTime.getMonth() + 1).padStart(2, "0");
const d = String(newTime.getDate()).padStart(2, "0");
const hh = String(newTime.getHours()).padStart(2, "0");
const mm = String(newTime.getMinutes()).padStart(2, "0");
const ss = String(newTime.getSeconds()).padStart(2, "0");

now.nowString = `วัน ${dayName} ที่ ${y}-${m}-${d} เวลา ${hh}:${mm}:${ss}`;
global.set("now", now);  // อัปเดตกลับ global

node.status({ fill: "blue", shape: "dot", text: now.nowString });
msg.payload = now.nowString;
