var moveState = global.get("moveState");
var poiOrder = data;
var countMoveStep = global.get("countMoveStep") || 0;
var poiMove = poiOrder[countMoveStep].POI;
var invertPose = poiOrder[countMoveStep].invertPose;
var backward = poiOrder[countMoveStep].moveBackward;
var orderLength = poiOrder.length;
var cancelMove = global.get("cancelMove") || false;

switch(moveState)
{
    case 1: // Moving to POI
        msg = {
            payload: {
                message: "Moving",
                POI: poiMove,
                invertPose: invertPose,
                moveBackward: backward
            },
            status:
            {
                fill: "blue",
                shape: "dot",
                // text: "Moving(" + (countMoveStep+1) + "/" + orderLength + "):" + poiMove
                text: `Moving(${countMoveStep+1}/${orderLength}): ${poiMove}
                        ${invertPose && !backward ? ' <InvertPose>' : ''}
                        ${!invertPose && backward ? ' <Backward>' : ''}
                        ${invertPose && backward ? ' <InvertPose & Backward>' : ''}
                        ${!invertPose && !backward ? '' : ''}`

            }
        }
        moveState = 0;
        global.set("moveState",moveState);
        return msg;

    case 2: // Cancel move
        poiOrder = [];
        global.set("poiOrder",poiOrder);
        countMoveStep = 0;
        global.set("countMoveStep",countMoveStep);
        cancelMove = false;
        global.set("cancelMove",cancelMove);
        msg = {
            payload:{
                message: "Cancel",
                position: poiMove
            },
            status:
            {
                fill: "red",
                shape: "dot",
                text: "Cancel"
            }
        }
        moveState = 0;
        global.set("moveState",moveState);
        return msg;

    case 3: // Move success
        poiOrder = [];
        global.set("poiOrder",poiOrder);
        countMoveStep = 0;
        global.set("countMoveStep",countMoveStep);
        msg = {
            payload:{
                message: "Success",
                position: poiMove
            },
            status:
            {
                fill: "green",
                shape: "dot",
                text: "Success"
            }
        }
        moveState = 0;
        global.set("moveState",moveState);
        return msg;

    case 4: //Can't move to target
        countMoveStep++;
        if(countMoveStep >= orderLength)
        {
            countMoveStep = 0;
        }
        global.set("countMoveStep",countMoveStep);
        moveState = 1;
        global.set("moveState",moveState);
        break;
}

