let count = context.get('count') || 0
var mode = env.get('mode')
var number = env.get('number')
var loop = env.get('loop') || 3
if (mode === 'detected'){
    if (msg.payload.detected === true){
        context.set('count',0)
        node.status({ fill: "green", shape: "dot", text: `Detected ID ${msg.payload.id}` });
        msg.payload = msg.payload.id
        return [msg,null,null]
    }
    count += 1;
    context.set('count',count);
    node.status({ fill: "blue", shape: "ring", text: count });
    if (count >= loop){
        context.set('count',0)
        msg.payload = 'Fail'
        node.status({ fill: "red", shape: "dot", text: 'Not Detected' });

        return [null,msg,null]
    }
}
else if (mode === 'number'){
    if (msg.payload.id === number){
        context.set('count',0)
        node.status({ fill: "green", shape: "dot", text: `Number ${number} Found`});

        return [msg,null,null]
    }
    count += 1;
    context.set('count',count);
    node.status({ fill: "blue", shape: "ring", text: count });
    if (count >= loop){
        context.set('count',0)
        msg.payload = 'Fail'
        node.status({ fill: "red", shape: "dot", text: 'Wrong Number' });

        return [null,msg,null]
    }
}
return [null,null,msg];

